insert into public.countries(code,data) values ('VN','{"date": "2026-11-10", "food": ["フォー｜米麺のスープ", "バインミー｜フランスパンのサンド"], "idx": 26.4, "safety": ["スリ｜ショッピングモール、バス、観光地、繁華街で多発。｜バッグは体の前でファスナーを閉め、現金は分けて持つ。", "バイクのひったくり｜バイクで背後から近づき、携帯電話やバッグを奪う。深夜に目立つ。｜路上でスマホを使わず、タクシーは店内で呼ぶ。", "タクシートラブル｜乱暴な運転、追加料金、高額請求がある。｜信頼できる会社か配車アプリを使い、車両ナンバーを確認する。", "カードのスキミング・ネット犯罪｜不正利用や、カード情報の読み取りがある。｜異常に気づいたら、すぐカード会社に連絡する。", "荷物の運搬依頼｜知人に頼まれた荷物に違法薬物が入っていて、逮捕される例がある。｜中身の分からない荷物は、親しい人からでも運ばない。", "賭博・売買春｜原則として犯罪で、少額でも逮捕・長期拘束の可能性がある。｜関わらない。"], "src": "Numbeo 2026年版（AOLの記事で確認）", "town": ["ハノイ｜旧市街が中心。コーヒー文化が強く作業場所も多い", "ダナン｜海に近く、落ち着いて作業しやすい", "ホーチミン｜最大の都市。コワーキングが多い"], "note": "物価が安く、カフェ文化が盛ん。バイクが多く交通ルールが独特。", "ssrc": "在ベトナム日本国大使館「安全の手引き」（2026年3月現在）", "night": ["全体｜売買春は犯罪で、少額でも逮捕・長期拘束の可能性がある。賭博も原則犯罪。｜関わらない。"], "nsrc": "在ベトナム日本国大使館「安全の手引き」（2026年3月）"}'::jsonb) on conflict (code) do nothing;
