insert into public.countries(code,data) values ('TH','{"est": 1, "food": ["パッタイ｜米麺の炒め", "カオソイ｜北部のカレー麺"], "idx": 38, "safety": ["スリ・置き引き・抱きつきスリ｜複数人で注意をそらす。子供や女性が体に触れて気を散らす手口もある。｜バッグは体の前に持ち、貴重品は体から離さない。", "バイクのひったくり｜歩道を歩いていると、後ろからバイクに荷物を奪われる。トゥクトゥク乗車中も狙われる。｜荷物は車道と反対側に持ち、乗り物でも体から離さない。", "睡眠薬強盗｜飲み物に睡眠薬を入れられ、金品を奪われたり、キャッシングを強いられたりする。｜初対面の人との飲食では、飲み物から目を離さない。", "オーダーメード詐欺（宝石・スーツ）｜観光地で声をかけられ、店に連れて行かれて高額な契約をさせられる。｜事前に店の評判と返金規定を確認する。", "見せ金・寸借詐欺｜「日本円を見せて」「お金を立て替えて」と近づいてくる。｜応じずに、その場を離れる。", "夜間のソンテオ（乗合タクシー）｜運転手に脅される例がある。｜夜の一人乗りを避け、他の客がいる車を選ぶ。", "闇バイト｜「短期間で高収入」で応募すると、現地で詐欺の「かけ子」や薬物の「運び屋」にされ、逮捕される恐れがある。｜安易に応募せず、知らない人の荷物は預からない。"], "town": ["チェンマイ｜ノマドの聖地、コワーキングとカフェが多い", "バンコク｜屋台と室内モールの巨大都市"], "note": "ノマドの定番。物価が手頃でビザ制度の確認が必要。", "ssrc": "在タイ日本国大使館 安全情報（2026年版）", "night": ["全体｜睡眠薬を飲み物に入れられ、金品を奪われる。裏通りの店での施術で、わいせつ行為の被害もある。｜初対面の人と飲むときは飲み物から目を離さず、店の評判を事前に調べる。"], "nsrc": "在タイ日本国大使館 安全情報（2026年版）"}'::jsonb) on conflict (code) do nothing;
