insert into public.countries(code,data) values ('CO','{"est": 1, "food": ["バンデハ・パイサ｜豆や肉をのせた大皿", "アレパ｜とうもろこし粉の丸いパン"], "idx": 32, "safety": ["SNS・アプリで知り合った人による睡眠薬強盗｜飲食物に睡眠薬を混ぜられる。｜アプリで知り合った人を安易に信用せず、持ち物から目を離さない。", "タクシー等の短時間強盗｜目的地以外に連れて行かれ、外国人が被害に遭う。｜人気のない道路は日中でも注意し、乗車中も警戒する。", "警察官のなりすまし｜職務質問を装い、金品をだまし取る。｜怪しい人物には警戒する。", "ひったくり・強盗｜抵抗すると危険。｜命を第一に、絶対に抵抗せず、盗品を取り返そうとしない。", "まきびしによるパンク｜わざとパンクさせ、高額な修理業者を紹介する。｜停車時も、周囲の不審者を確認する。", "ホテルでの盗難｜ロッカーを壊され、旅券やパソコンが盗まれた例がある。｜貴重品から目を離さない。"], "town": ["メデジン｜気候が穏やかで、ノマドが多い", "ボゴタ｜標高が高い首都。文化施設が豊富"], "note": "観光客が増えている。都市によって治安が違う。", "ssrc": "在コロンビア日本国大使館「海外安全対策情報」（2024年10〜12月）"}'::jsonb) on conflict (code) do nothing;
insert into public.countries(code,data) values ('SB','{"date": "2026-11-10", "idx": 102.3, "src": "Numbeo 2026年版（Thomas Cook Indiaの記事で確認）", "note": "島国で、インフラが限られる。", "town": ["ホニアラ｜首都。"], "safety": ["強盗｜都市部。｜夜の外出は避ける。", "病気｜マラリア。｜予防する。"]}'::jsonb) on conflict (code) do nothing;
insert into public.countries(code,data) values ('KH','{"est": 1, "food": ["アモック｜ココナッツの蒸しカレー"], "idx": 40, "safety": ["バイクのひったくり｜バイクで後ろから近づき、バッグを強く引っ張る。トゥクトゥクやバイクタクシー乗車中に狙われ、転倒して重傷の例もある。｜バッグは持たずに、リュックを両肩で背負う。バイクタクシーは避ける。", "強盗（拳銃・ナイフ）｜夜の裏通りやカジノ周辺で襲われる。ナイフで肩紐を切って奪う手口もある。｜夜は人の少ない場所やカジノ周辺を避け、襲われたら身の安全を優先する。", "スリ・置き引き｜物乞いの子供などが近づき、注意をそらす。席に置いたバッグが盗まれる。｜人混みではバッグを前に持ち、席を離れるときは持ち歩く。", "いかさま賭博詐欺｜片言の日本語で近づき、自宅に誘って、いかさま賭博で高額を要求する。｜見知らぬ人の誘いには応じず、宿や連絡先を教えない。", "昏睡強盗｜バーやレストランで知り合った人と飲酒し、酔った隙に財布を盗まれる。｜見知らぬ外国人との飲酒を避ける。", "交通事故｜事故後に逃げると、住民に追われて暴行を受ける例がある。｜保険に加入し、事故時は逃げずに救護と通報をする。"], "town": ["プノンペン｜首都。川沿いにカフェが多い", "シェムリアップ｜遺跡観光の拠点。長期滞在者も多い"], "note": "ドルが使える。物価は安いが、都市の治安に注意。", "ssrc": "在カンボジア日本国大使館「海外安全対策情報」（2018年ごろ。古い情報を含む）", "night": ["全体｜夜の裏通りやカジノ周辺で、拳銃やナイフの強盗が起きる。片言の日本語で近づき、いかさま賭博に誘う詐欺もある。｜夜はカジノ周辺や人の少ない場所を避け、見知らぬ人の誘いに乗らない。"], "nsrc": "在カンボジア日本国大使館「海外安全対策情報」（2018年ごろ）"}'::jsonb) on conflict (code) do nothing;
