insert into public.countries(code,data) values ('MX','{"date": "2026-11-10", "food": ["タコス｜トルティーヤに具をはさむ定番"], "idx": 42.6, "safety": ["強盗｜銃やナイフで脅される。信号待ちの車が襲われることもある。｜抵抗せず、身の安全を優先する。捨て財布を用意する。", "昏睡強盗｜飲食物に睡眠薬を混ぜられ、意識を失って金品を奪われる。｜初対面の人と飲食せず、席を離れるときは飲み物から目を離さない。", "流しのタクシー・短時間誘拐｜短時間拘束され、ATMで現金を引き出させられる。｜予約制のタクシーか配車アプリを使い、夜の一人利用を避ける。", "ケチャップスリ｜服に汚れを付け、拭くふりをして財布を抜く。｜近寄る人には礼を言って離れ、財布を複数に分ける。", "バーチャル誘拐｜実際には誘拐せず、電話で家族を脅して送金させる。｜知らない番号に出ず、不審ならすぐ切る。", "車上ねらい｜窓を割って、短時間で荷物を盗む。｜車内にもトランクにも荷物を残さない。"], "src": "Numbeo 2026年版（Thomas Cook Indiaの記事で確認）", "town": ["メキシコシティ｜大都市。ノマド向けの地区が多い", "プラヤ・デル・カルメン｜カリブ海沿いのリゾート"], "note": "観光地が多い。地域によって治安が大きく違う。", "ssrc": "在メキシコ日本国大使館「安全の手引き」（2026年1月改訂）"}'::jsonb) on conflict (code) do nothing;
