insert into public.countries(code,data) values ('MY','{"est": 1, "food": ["ナシレマ｜ココナッツご飯のワンプレート", "ラクサ｜スパイシーな麺スープ"], "idx": 34, "safety": ["MDAC（デジタル入国カード）の偽サイト｜正規の登録は無料だが、偽サイトは手数料名目でカード情報を求める。｜公式サイトだけを使い、カード情報を入力しない。", "警察・銀行員・政府機関をかたる詐欺｜電話やSMS、WhatsAppで、送金や個人情報を求める。｜心当たりがなければ無視し、本人から確認する。", "投資・ロマンス詐欺｜SNSやマッチングアプリで親しくなり、投資や金銭の話を持ちかける。｜会ったことのない相手には送金しない。", "「お金見せて」詐欺｜日本円を見せてと近づき、隙に紙幣を抜き取る。｜財布や紙幣を、見知らぬ人に見せない。", "賃貸・学費の詐欺｜個人口座への送金を求める、他人名義の物件を貸す。｜送金先が公式か、仲介業者の身元を確認する。"], "town": ["クアラルンプール｜コワーキングと屋台が豊富な都会", "ペナン・ジョージタウン｜世界遺産の街でグルメが安い"], "note": "英語が通じ、物価は手頃。ビザや長期滞在の制度が整っている。", "ssrc": "在マレーシア日本国大使館「安全の手引き」（2026年版）"}'::jsonb) on conflict (code) do nothing;
